"""Responsive styles for the shared timetable and availability preparation page."""
CSS = '''
:root{color-scheme:light;--ink:#20302d;--muted:#586762;--line:#d6ded9;--accent:#25614c;--paper:#f6f7f3}
*{box-sizing:border-box}body{margin:0;background:var(--paper);color:var(--ink);font:16px/1.55 system-ui,sans-serif}
main.planning-page{width:min(100%,1024px);margin:auto;padding:40px 24px 64px}h1{font-size:clamp(28px,5vw,40px);line-height:1.2;margin:22px 0}h2{font-size:23px;line-height:1.3}h3{font-size:19px}p{max-width:78ch}a{color:var(--accent);text-underline-offset:3px}a:hover{text-decoration-thickness:2px}
.planning-page>section,.planning-page>form{background:white;border:1px solid var(--line);border-radius:16px;padding:24px;margin:24px 0}form{margin-top:20px}fieldset{min-width:0;border:1px solid var(--line);border-radius:10px;margin:16px 0;padding:16px}legend{font-weight:600;padding:0 8px}
label{display:block;font-weight:550;margin:14px 0 6px}input,select,button{font:inherit;border-radius:8px;min-height:44px;max-width:100%}input,select{width:100%;padding:9px 12px;border:1px solid #8b9e93;background:white;color:var(--ink)}input[type=checkbox]{width:20px;min-height:20px;vertical-align:middle;margin-right:8px}input[type=file]{padding:8px}button{padding:10px 16px;border:1px solid #97aa9f;background:#edf3ed;color:var(--ink);cursor:pointer;margin:10px 8px 6px 0}button[type=submit],#classes-import{background:var(--accent);border-color:var(--accent);color:white}button:disabled,input:disabled,select:disabled{opacity:.6;cursor:default}button:hover:not(:disabled){filter:brightness(.94)}:focus-visible{outline:3px solid #b86e15;outline-offset:3px}[hidden]{display:none!important}
[role=status]{padding:10px 0;font-weight:500;overflow-wrap:anywhere}ul{padding-left:22px}#planning-inputs form{border-top:1px solid var(--line);padding-top:16px}#classes-rows{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:16px}#classes-rows>fieldset{margin:10px 0}#classes-rows input[type=time]{width:100%}
@media(max-width:640px){main.planning-page{padding:24px 16px 48px}.planning-page>section,.planning-page>form{padding:16px}#classes-rows{grid-template-columns:1fr;gap:8px}fieldset{padding:12px}button{width:100%;margin-right:0}h2{font-size:21px}}
'''
